/* data/cs-c/cs-12-06.js - GENERATED by tools/build.py from data/cs/cs-12-06.json. Questions are the board's; answers are our own words. Do not edit. */
(window.CS_C = window.CS_C || {})["cs-12-06"] = [{"id":"cs-12-06-01","kind":"short","q":"Why 8085 is called 8 bit microprocessor ?","marks":3,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.1"],"model":[{"t":"The 8085 has an 8-bit data bus, so it can send or receive 8 bits of data at a time.","m":1},{"t":"Its ALU and its main registers (A, B, C, D, E, H, L) are 8 bits wide, so it works on 8-bit data in one operation.","m":1},{"t":"The word size is the size of the data it handles, not the size of the address (the address is 16 bits).","m":1}]},{"id":"cs-12-06-02","kind":"short","q":"What do you mean by addressing modes of microprocessor ?","marks":3,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.2"],"model":[{"t":"An addressing mode is the way in which an instruction tells where its data (the operand) is.","m":1},{"t":"The data may be in the instruction itself, in a register, or at a memory location.","m":1},{"t":"Different modes let the programmer write short and flexible programs.","m":1}]},{"id":"cs-12-06-03","kind":"short","q":"List the five addressing modes of 8085.","marks":4,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.3"],"model":[{"t":"Immediate addressing: the data is part of the instruction. Example: MVI A, 05H.","m":1},{"t":"Register addressing: the data is in a register. Example: MOV A, B.","m":1},{"t":"Direct addressing: the instruction gives the memory address of the data. Example: LDA 2000H.","m":1},{"t":"Register indirect addressing: a register pair holds the memory address. Example: MOV A, M. Implied addressing: the instruction needs no operand. Example: CMA.","m":1}]},{"id":"cs-12-06-04","kind":"short","q":"What are data transfer instructions ? List five data transfer instructions.","marks":4,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.4"],"model":[{"t":"Data transfer instructions copy data from a source to a destination (register, memory or I/O port).","m":1},{"t":"The source is not changed, and no flag is affected.","m":1},{"t":"Five of them: MOV (register to register or memory), MVI (immediate data into a register).","m":1},{"t":"LDA (memory to accumulator), STA (accumulator to memory) and LXI (16-bit data into a register pair). Others: LHLD, SHLD, XCHG, LDAX, STAX.","m":1}]},{"id":"cs-12-06-05","kind":"prog","q":"Describe Programming model of 8085.","marks":5,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.5"],"model":[{"t":"The programming model shows the registers that a programmer can use.","m":1},{"t":"Accumulator A and the six general purpose registers B, C, D, E, H and L (8 bits each); they can work in pairs BC, DE and HL.","m":1},{"t":"The flag register with five flags: S, Z, AC, P and CY.","m":1},{"t":"The 16-bit program counter (PC) and stack pointer (SP).","m":1},{"t":"A neat diagram of the model is drawn with the bit sizes.","m":1}],"code":"            7                 0\n  Accumulator [        A         ]\n  Flags       [ S  Z  -  AC -  P  -  CY ]\n\n  General purpose registers (8 bit):\n     [   B   ] [   C   ]     pair BC\n     [   D   ] [   E   ]     pair DE\n     [   H   ] [   L   ]     pair HL  (also used as memory pointer M)\n\n  15                                  0\n  Stack pointer   [          SP          ]\n  Program counter [          PC          ]"},{"id":"cs-12-06-06","kind":"short","q":"What is purpose of XCHG instruction ?","marks":3,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.6"],"model":[{"t":"XCHG exchanges the contents of the register pair HL with the register pair DE.","m":1},{"t":"H and D are exchanged, and L and E are exchanged.","m":1},{"t":"It is a 1-byte instruction with implied addressing, and it affects no flag.","m":1}]},{"id":"cs-12-06-07","kind":"short","q":"List arithmetic instructions of 8085.","marks":4,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.7"],"model":[{"t":"Addition: ADD, ADC (add with carry), ADI (add immediate), ACI (add immediate with carry).","m":1},{"t":"Subtraction: SUB, SBB (subtract with borrow), SUI, SBI.","m":1},{"t":"Increment and decrement: INR, DCR (8 bit) and INX, DCX (register pair).","m":1},{"t":"16-bit addition DAD, and decimal adjust DAA.","m":1}]},{"id":"cs-12-06-08","kind":"short","q":"How many logical instructions 8085 have ? List them.","marks":4,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.8"],"model":[{"t":"The logical group of the 8085 has these instructions, and they work on the accumulator.","m":1},{"t":"AND, OR and XOR: ANA, ANI, ORA, ORI, XRA, XRI.","m":1},{"t":"Compare: CMP, CPI. Complement and carry: CMA, CMC, STC.","m":1},{"t":"Rotate: RLC, RRC, RAL, RAR.","m":1}]},{"id":"cs-12-06-09","kind":"short","q":"What are branching instructions for 8085 ?","marks":4,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.9"],"model":[{"t":"Branching instructions change the normal order of the program by loading a new address into the program counter.","m":1},{"t":"Jump instructions: unconditional JMP and conditional jumps JC, JNC, JZ, JNZ, JP, JM, JPE, JPO.","m":1},{"t":"Call and return: CALL, RET and their conditional forms. Restart: RST n.","m":1},{"t":"A conditional branch is taken only if the flag in its condition is set (or reset); PCHL loads PC from HL.","m":1}]},{"id":"cs-12-06-10","kind":"short","q":"Explain purpose of PUSH instruction for 8085 ?","marks":3,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.10"],"model":[{"t":"PUSH saves the contents of a register pair on the stack: PUSH B, PUSH D, PUSH H or PUSH PSW (A and flags).","m":1},{"t":"The high-order register is stored at address SP - 1, the low-order register at SP - 2, and then SP is decreased by 2.","m":1},{"t":"It is used to save data before a subroutine and it is a 1-byte instruction.","m":1}]},{"id":"cs-12-06-11","kind":"short","q":"What is POP instruction for 8085 ?","marks":3,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.11"],"model":[{"t":"POP takes the top two bytes of the stack back into a register pair: POP B, POP D, POP H or POP PSW.","m":1},{"t":"The low-order register gets the byte at address SP, the high-order register gets the byte at SP + 1, and then SP is increased by 2.","m":1},{"t":"It is the opposite of PUSH, and registers must be popped in the reverse order in which they were pushed.","m":1}]},{"id":"cs-12-06-12","kind":"short","q":"Write the contents of accumulator after RIM instruction in 8085.","marks":4,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.12"],"model":[{"t":"After RIM the accumulator holds the serial input bit and the state of the interrupts.","m":1},{"t":"Bit D7 = the bit on the SID pin. Bits D6, D5, D4 = pending interrupts I7.5, I6.5, I5.5.","m":1},{"t":"Bit D3 = interrupt enable flag (IE).","m":1},{"t":"Bits D2, D1, D0 = the masks M7.5, M6.5, M5.5 (1 means masked).","m":1}]},{"id":"cs-12-06-13","kind":"short","q":"What do you mean by maskable and nonmaskable interrupts ?","marks":3,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.13"],"model":[{"t":"A maskable interrupt can be disabled (masked) by the program with DI or with the masks of the SIM instruction: INTR, RST 7.5, RST 6.5 and RST 5.5.","m":1},{"t":"A non-maskable interrupt cannot be disabled by the program, and it is always served at once: TRAP.","m":1},{"t":"Non-maskable interrupts are used for very urgent events like power failure.","m":1}]},{"id":"cs-12-06-14","kind":"short","q":"Describe the steps in processing RST 5.5 interrupt.","marks":5,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.14"],"model":[{"t":"An outside device sends a high level on the RST 5.5 pin; the interrupts must be enabled (EI) and RST 5.5 must not be masked.","m":1},{"t":"The microprocessor finishes the instruction it is doing and does not take other interrupts of lower priority.","m":1},{"t":"It saves the program counter (the return address) on the stack and disables the interrupt system.","m":1},{"t":"It jumps to the fixed vector address of RST 5.5, which is 002CH, where the service routine starts.","m":1},{"t":"The routine does the work, ends with EI and RET; RET pops the return address into PC and the main program continues.","m":1}]},{"id":"cs-12-06-15","kind":"short","q":"Describe the general format of Assembly language programs.","marks":4,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.15"],"model":[{"t":"An assembly language statement is written in four fields: label, mnemonic (operation), operand and comment.","m":1},{"t":"The label is a name for the address of the instruction and ends with a colon (it is optional).","m":1},{"t":"The mnemonic is the name of the instruction, and the operand is the data or the address it uses.","m":1},{"t":"The comment starts with a semicolon and explains the line. Example:  START: MVI A, 05H ; load 05H in A","m":1}]},{"id":"cs-12-06-16","kind":"prog","q":"Write assembly language program to arrange two numbers in descending order.","marks":5,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.16"],"model":[{"t":"The two numbers are in memory locations 2000H and 2001H; the answer will be in the same places.","m":1},{"t":"The first number is loaded and kept in register B, and the second is loaded in the accumulator.","m":1},{"t":"CMP B compares them; the carry flag shows which is smaller.","m":1},{"t":"If the numbers are already in descending order the program jumps to the end; otherwise they are exchanged and stored.","m":1},{"t":"The program ends with HLT.","m":1}],"code":"       LDA  2000H    ; A = first number\n       MOV  B,A      ; B = first number\n       LDA  2001H    ; A = second number\n       CMP  B        ; A - B : carry set if second < first\n       JC   DONE     ; already in descending order\n       STA  2000H    ; larger number goes first\n       MOV  A,B\n       STA  2001H    ; smaller number goes second\nDONE:  HLT","checks":[{"mem":{"2000":[5,9]},"expect":{"2000":[9,5]}},{"mem":{"2000":[9,5]},"expect":{"2000":[9,5]}},{"mem":{"2000":[7,7]},"expect":{"2000":[7,7]}}]},{"id":"cs-12-06-17","kind":"prog","q":"Write assembly language program for addition of two 16-bit numbers.","marks":5,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.17"],"model":[{"t":"The first number is at 2000H (low byte) and 2001H (high byte), the second at 2002H and 2003H.","m":1},{"t":"LHLD loads a 16-bit number into HL; XCHG moves the first number into DE; LHLD loads the second into HL.","m":1},{"t":"DAD D adds DE to HL; the carry flag is set if the sum is larger than 16 bits.","m":1},{"t":"SHLD stores the 16-bit sum; the carry is turned into a byte and stored at 2006H.","m":1},{"t":"The program ends with HLT.","m":1}],"code":"       LHLD 2000H    ; HL = first 16-bit number\n       XCHG          ; DE = first number\n       LHLD 2002H    ; HL = second number\n       DAD  D        ; HL = HL + DE, carry flag shows overflow\n       SHLD 2004H    ; store the 16-bit sum\n       MVI  A,00H\n       ADC  A        ; A = 0 + 0 + carry\n       STA  2006H    ; store the carry byte\n       HLT","checks":[{"mem":{"2000":[52,18,120,86]},"expect":{"2004":[172,104,0]}},{"mem":{"2000":[255,255,2,0]},"expect":{"2004":[1,0,1]}}]},{"id":"cs-12-06-18","kind":"prog","q":"Write assembly language program to rotate data in 2000 H by two bit positions to the left side.","marks":4,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.18"],"model":[{"t":"The data is loaded from 2000H into the accumulator with LDA.","m":1},{"t":"RLC rotates the accumulator one bit to the left, so it is written twice.","m":1},{"t":"The result is stored with STA (here at 2001H).","m":1},{"t":"The program ends with HLT.","m":1}],"code":"       LDA  2000H    ; A = data\n       RLC           ; rotate left by one bit\n       RLC           ; and by one more bit\n       STA  2001H    ; store the result\n       HLT","checks":[{"mem":{"2000":[129]},"expect":{"2001":[6]}},{"mem":{"2000":[53]},"expect":{"2001":[212]}}]},{"id":"cs-12-06-19","kind":"prog","q":"Write assembly language program to obtain 2's complement of contents of 2000 H.","marks":4,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.19"],"model":[{"t":"The data is loaded from 2000H into the accumulator.","m":1},{"t":"CMA gives the 1's complement (every bit is changed).","m":1},{"t":"ADI 01H adds 1, which gives the 2's complement.","m":1},{"t":"The result is stored (here at 2001H) and the program ends with HLT.","m":1}],"code":"       LDA  2000H    ; A = data\n       CMA           ; 1's complement\n       ADI  01H      ; add 1 : 2's complement\n       STA  2001H    ; store the result\n       HLT","checks":[{"mem":{"2000":[5]},"expect":{"2001":[251]}},{"mem":{"2000":[0]},"expect":{"2001":[0]}},{"mem":{"2000":[128]},"expect":{"2001":[128]}}]},{"id":"cs-12-06-m20a","kind":"mcq","q":"CMC instruction of 8085 uses .......... addressing mode.","marks":1,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.20(a)"],"options":["Direct","Implied","Indirect","Register"],"ans":1,"why":"CMC (complement carry) names no operand: the carry flag is implied. So it uses implied addressing."},{"id":"cs-12-06-m20b","kind":"mcq","q":"MVI A instruction of 8085 uses .......... addressing mode.","marks":1,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.20(b)"],"options":["Direct","Implied","Immediate","Indirect"],"ans":2,"why":"In MVI A, 05H the data 05H is inside the instruction itself: immediate addressing."},{"id":"cs-12-06-m20c","kind":"mcq","q":"MOV A, M instruction of 8085 uses .......... machine cycles.","marks":1,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.20(c)"],"options":["2","1","3","4"],"ans":0,"why":"One cycle fetches the opcode and a second reads the data from the memory location pointed to by HL: 2 machine cycles."},{"id":"cs-12-06-m20d","kind":"mcq","q":"The INXH instruction of 8085 affects .......... flags","marks":1,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.20(d)"],"options":["zero","parity","carry","no"],"ans":3,"why":"INX (increment register pair) affects no flag. INR (8 bit) does affect them."},{"id":"cs-12-06-m20f","kind":"mcq","q":"ORI instruction of 8085 is .......... byte instruction.","marks":1,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.20(f)"],"options":["1","2","3","4."],"ans":1,"why":"ORI has one byte for the opcode and one byte for the immediate data: 2 bytes."},{"id":"cs-12-06-m20g","kind":"mcq","q":"Push (rp) instruction of 8085 affects the ..........","marks":1,"src":["Guide ch.6 Instruction Set and Programming of 8085, Q.20(g)"],"options":["HL register","PC","SP","None of these."],"ans":2,"why":"PUSH stores two bytes on the stack, so the stack pointer SP goes down by 2."}];
